#define XSSH_CHANNEL_OPEN_ADMINISTRATIVELY_PROHIBITED 1u
#define XSSH_CHANNEL_OPEN_CONNECT_FAILED 2u
#define XSSH_CHANNEL_OPEN_UNKNOWN_CHANNEL_TYPE 3u
#define XSSH_CHANNEL_OPEN_RESOURCE_SHORTAGE 4u

